slides.solution:
def has_duplicates(items):
    seen = set()
    for item in items:
        if item in seen:
            return True
        seen.add(item)
    return False

print(has_duplicates(["riya@x.in", "arjun@x.in", "riya@x.in"]))

slides.tests:
assert has_duplicates(["a", "b", "a"]) is True, "['a', 'b', 'a'] has a repeat, so return True."
assert has_duplicates([1, 2, 3]) is False, "[1, 2, 3] has no repeats, so return False."
assert has_duplicates([]) is False, "An empty list has no duplicates: return False."

class Email:
    compares = 0
    def __init__(self, v):
        self.v = v
    def __eq__(self, other):
        Email.compares += 1
        return self.v == other.v
    def __lt__(self, other):
        Email.compares += 1
        return self.v < other.v
    def __hash__(self):
        return hash(self.v)

assert has_duplicates([Email(i) for i in range(400)]) is False, "400 different emails: return False."
assert Email.compares < 20000, f"Your function made {Email.compares:,} comparisons for just 400 emails: that is O(n²). Remember each item in a set, so every check is one hash lookup."

