assert missing(3, [3, 1, 2]) == [], "Everyone submitted, so return an empty list."
assert missing(4, []) == [1, 2, 3, 4], "Nobody submitted: every roll from 1 to 4 is missing."

class Watched(list):
    scans = 0
    def __contains__(self, x):
        Watched.scans += 1
        return list.__contains__(self, x)
    def count(self, x):
        Watched.scans += 1
        return list.count(self, x)
    def index(self, *args):
        Watched.scans += 1
        return list.index(self, *args)

assert missing(1000, Watched(range(1, 1001, 2))) == list(range(2, 1001, 2)), "With only odd rolls submitted, the even rolls 2 to 1000 are missing."
assert Watched.scans <= 5, "You searched the submitted list once per student, which is O(n²). Turn it into a set first, then check the set."
